package com.nexusdrive.metadata.service.impl;
import com.nexusdrive.common.exception.*;import com.nexusdrive.common.util.*;import com.nexusdrive.metadata.dto.*;import com.nexusdrive.metadata.entity.*;import com.nexusdrive.metadata.repository.*;import com.nexusdrive.metadata.service.*;import java.io.*;import java.nio.file.*;import java.security.*;import java.util.*;import javax.crypto.SecretKey;import javax.crypto.spec.SecretKeySpec;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service@Transactional public class FileMetadataServiceImpl implements FileMetadataService{public static final int CHUNK_SIZE=8*1024*1024;private final FileMetadataRepository files;private final FolderRepository folders;private final ChunkRepository chunks;private final FileVersionRepository versions;private final DeduplicationService dedup;private final ChunkOrchestrationService storage;private final KeyProtectionService keys;public FileMetadataServiceImpl(FileMetadataRepository f,FolderRepository fo,ChunkRepository c,FileVersionRepository v,DeduplicationService d,ChunkOrchestrationService s,KeyProtectionService k){files=f;folders=fo;chunks=c;versions=v;dedup=d;storage=s;keys=k;}
 public FileMetadata initialize(UUID owner,FileUploadRequest r){Folder folder=r.folderId()==null?null:folders.findByIdAndOwnerId(r.folderId(),owner).orElseThrow(()->new ResourceNotFoundException("Folder not found"));FileMetadata f=new FileMetadata();f.setOwnerId(owner);f.setFolder(folder);f.setFilename(r.filename());f.setMimeType(r.mimeType());f.setSizeBytes(r.sizeBytes());f.setTags(r.tags()==null?new String[0]:r.tags().toArray(String[]::new));f.setExpectedChunks((int)((r.sizeBytes()+CHUNK_SIZE-1)/CHUNK_SIZE));f.setContentHash(r.contentHash());Optional<FileMetadata> match=dedup.findDuplicate(r.contentHash());if(match.isPresent()){FileMetadata s=match.get();f.setEncryptionKeyRef(s.getEncryptionKeyRef());f.setStatus(FileMetadata.Status.ACTIVE);f=files.save(f);dedup.cloneChunks(s,f);version(f);return f;}SecretKey key=AesEncryptionUtil.generateKey();f.setEncryptionKeyRef(keys.protect(key));f=files.save(f);for(int i=0;i<f.getExpectedChunks();i++){Chunk c=new Chunk();c.setFile(f);c.setChunkIndex(i);String objectKey=chunkId(f.getId(),i);c.setStorageKey(objectKey);String primary=storage.primary(objectKey);c.setStorageNodeId(primary);c.setReplicaNodeIds(storage.replicas(primary).toArray(String[]::new));chunks.save(c);}return f;}
 public FileMetadata upload(UUID owner,String name,String mime,UUID folder,String[] tags,InputStream input,long size){Path temp=null;try{temp=Files.createTempFile("nexusdrive-upload-",".tmp");MessageDigest digest=MessageDigest.getInstance("SHA-256");try(var out=Files.newOutputStream(temp);var checked=new DigestInputStream(input,digest)){checked.transferTo(out);}if(Files.size(temp)!=size)throw new ValidationException("Upload size changed during transfer");String hash=HexFormat.of().formatHex(digest.digest());FileMetadata f=initialize(owner,new FileUploadRequest(name,mime,size,folder,tags==null?List.of():Arrays.asList(tags),hash));if(f.getStatus()==FileMetadata.Status.ACTIVE)return f;try(var in=Files.newInputStream(temp)){for(int i=0;;i++){byte[] data=in.readNBytes(CHUNK_SIZE);if(data.length==0)break;uploadChunk(owner,f.getId(),i,data);}}if(size==0)complete(f);return files.findById(f.getId()).orElseThrow();}catch(IOException e){throw new UncheckedIOException(e);}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}finally{if(temp!=null)try{Files.deleteIfExists(temp);}catch(IOException ignored){}}}
 public void uploadChunk(UUID owner,UUID id,int index,byte[] plain){FileMetadata f=owned(owner,id);if(f.getStatus()!=FileMetadata.Status.UPLOADING)throw new ValidationException("File is not accepting chunks");if(index<0||index>=f.getExpectedChunks())throw new ValidationException("Chunk index out of range");int expected=index==f.getExpectedChunks()-1?(int)(f.getSizeBytes()-(long)index*CHUNK_SIZE):CHUNK_SIZE;if(plain.length!=expected)throw new ValidationException("Chunk size mismatch: expected "+expected);Chunk c=chunks.findByFileIdAndChunkIndex(id,index).orElseThrow();String checksum=Sha256HashUtil.hash(plain);byte[] encrypted=AesEncryptionUtil.encrypt(plain,key(f));storage.put(c.getStorageNodeId(),c.getStorageKey(),encrypted);c.setChecksum(checksum);c.setPlainSize(plain.length);c.setUploaded(true);chunks.save(c);if(chunks.countByFileIdAndUploadedTrue(id)==f.getExpectedChunks())complete(f);}
 public ChunkStatusResponse status(UUID o,UUID id){FileMetadata f=owned(o,id);Set<Integer> up=new TreeSet<>();chunks.findByFileIdOrderByChunkIndex(id).stream().filter(Chunk::isUploaded).forEach(c->up.add(c.getChunkIndex()));List<Integer> missing=new ArrayList<>();for(int i=0;i<f.getExpectedChunks();i++)if(!up.contains(i))missing.add(i);return new ChunkStatusResponse(id,f.getExpectedChunks(),new ArrayList<>(up),missing,missing.isEmpty());}
 @Transactional(readOnly=true)public void download(UUID user,UUID id,OutputStream out){FileMetadata f=getAccessible(user,id);try{for(Chunk c:chunks.findByFileIdOrderByChunkIndex(id)){byte[] plain=AesEncryptionUtil.decrypt(storage.getWithFailover(c.getStorageNodeId(),c.getReplicaNodeIds(),c.getStorageKey()),key(f));if(!Sha256HashUtil.hash(plain).equals(c.getChecksum()))throw new IllegalStateException("Chunk integrity check failed");out.write(plain);out.flush();}}catch(IOException e){throw new UncheckedIOException(e);}}public FileMetadata getAccessible(UUID user,UUID id){FileMetadata f=files.findAccessible(id,user).orElseThrow(()->new ResourceNotFoundException("File not found"));if(f.getStatus()!=FileMetadata.Status.ACTIVE)throw new ResourceNotFoundException("File not active");return f;}
 public void delete(UUID o,UUID id){FileMetadata f=owned(o,id);f.setStatus(FileMetadata.Status.DELETED);files.save(f);}private void complete(FileMetadata f){f.setStatus(FileMetadata.Status.ACTIVE);files.save(f);version(f);}private void version(FileMetadata f){if(f.getContentHash()==null){try{MessageDigest md=MessageDigest.getInstance("SHA-256");for(Chunk c:chunks.findByFileIdOrderByChunkIndex(f.getId()))md.update(AesEncryptionUtil.decrypt(storage.getWithFailover(c.getStorageNodeId(),c.getReplicaNodeIds(),c.getStorageKey()),key(f)));f.setContentHash(HexFormat.of().formatHex(md.digest()));files.save(f);}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}FileVersion v=new FileVersion();v.setFile(f);v.setVersionNumber(1);v.setSizeBytes(f.getSizeBytes());v.setContentHash(f.getContentHash());versions.save(v);}private FileMetadata owned(UUID o,UUID id){return files.findByIdAndOwnerId(id,o).orElseThrow(()->new ResourceNotFoundException("File not found"));}private SecretKey key(FileMetadata f){return keys.unprotect(f.getEncryptionKeyRef());}private String chunkId(UUID id,int i){return id+"-"+i;}}
